      'If using Bitcoin, you can use RBF (Replace-By-Fee) to speed it up': 'Si vous utilisez Bitcoin, vous pouvez utiliser le RBF (Replace-By-Fee) pour l\'accélérer',
      'If you are new to cryptocurrency, we recommend reading our Terms of Service and Privacy Policy first.': 'Si vous débutez dans les cryptomonnaies, nous vous recommandons de lire d\'abord nos Conditions d\'utilisation et notre Politique de confidentialité.',
      'If you forgot your password but have your seed phrase, you can import your wallet using the seed phrase and set a new password. Go to import.html and select "Mnemonic Phrase".': 'Si vous avez oublié votre mot de passe mais avez votre phrase de récupération, vous pouvez importer votre portefeuille en utilisant la phrase de récupération et définir un nouveau mot de passe. Allez sur import.html et sélectionnez « Phrase mnémonique ».',
      'If you have your password, you can still access your wallet. However, if you lose both your password and seed phrase, your wallet cannot be recovered. This is why it is crucial to back up your seed phrase in a secure location.': 'Si vous avez votre mot de passe, vous pouvez toujours accéder à votre portefeuille. Cependant, si vous perdez à la fois votre mot de passe et votre phrase de récupération, votre portefeuille ne peut pas être récupéré. C\'est pourquoi il est crucial de sauvegarder votre phrase de récupération dans un endroit sûr.',
