      'Navigate to the "Address Check" page from the dashboard or main menu.': 'Accédez à la page « Vérification d\'adresse » depuis le tableau de bord ou le menu principal.',
      'Network fees fluctuate based on blockchain congestion. When many users are transacting simultaneously, fees increase due to higher demand for block space. During quiet periods, fees are lower. Bitcoin and Ethereum typically have the most variable fees.': 'Les frais de réseau fluctuent en fonction de la congestion de la blockchain. Lorsque de nombreux utilisateurs effectuent des transactions simultanément, les frais augmentent en raison d\'une demande plus élevée d\'espace de bloc. Pendant les périodes calmes, les frais sont plus bas. Bitcoin et Ethereum ont généralement les frais les plus variables.',
      'Network fees vary depending on blockchain congestion. Higher network fees result in faster transaction confirmation.': 'Les frais de réseau varient selon la congestion de la blockchain. Des frais réseau plus élevés entraînent une confirmation de transaction plus rapide.',
      'Never share your seed phrase with anyone. Anyone with access to your seed phrase can control your wallet.': 'Ne partagez jamais votre phrase de récupération avec qui que ce soit. Toute personne ayant accès à votre phrase de récupération peut contrôler votre portefeuille.',
