      'ID': 'ID',
      'If using Bitcoin, you can use RBF (Replace-By-Fee) to speed it up': 'Bei Bitcoin können Sie RBF (Replace-By-Fee) verwenden, um es zu beschleunigen',
      'If you are new to cryptocurrency, we recommend reading our Terms of Service and Privacy Policy first.': 'Wenn Sie neu bei Kryptowährung sind, empfehlen wir, zuerst unsere Nutzungsbedingungen und Datenschutzrichtlinie zu lesen.',
      'If you forgot your password but have your seed phrase, you can import your wallet using the seed phrase and set a new password. Go to import.html and select "Mnemonic Phrase".': 'Wenn Sie Ihr Passwort vergessen haben, aber Ihre Seed-Phrase besitzen, können Sie Ihr Wallet mit der Seed-Phrase importieren und ein neues Passwort festlegen. Gehen Sie zu import.html und wählen Sie "Mnemonische Phrase".',
      'If you have your password, you can still access your wallet. However, if you lose both your password and seed phrase, your wallet cannot be recovered. This is why it is crucial to back up your seed phrase in a secure location.': 'Wenn Sie Ihr Passwort haben, können Sie weiterhin auf Ihr Wallet zugreifen. Wenn Sie jedoch sowohl Ihr Passwort als auch Ihre Seed-Phrase verlieren, kann Ihr Wallet nicht wiederhergestellt werden. Deshalb ist es entscheidend, Ihre Seed-Phrase an einem sicheren Ort zu sichern.',
