      'Navigate to the "Address Check" page from the dashboard or main menu.': 'Navigieren Sie vom Dashboard oder Hauptmenü zur Seite "Adressprüfung".',
      'Network fees fluctuate based on blockchain congestion. When many users are transacting simultaneously, fees increase due to higher demand for block space. During quiet periods, fees are lower. Bitcoin and Ethereum typically have the most variable fees.': 'Netzwerkgebühren schwanken je nach Auslastung der Blockchain. Wenn viele Benutzer gleichzeitig Transaktionen durchführen, steigen die Gebühren aufgrund der höheren Nachfrage nach Blockspeicherplatz. In ruhigen Zeiten sind die Gebühren niedriger. Bitcoin und Ethereum haben in der Regel die am stärksten variierenden Gebühren.',
      'Network fees vary depending on blockchain congestion. Higher network fees result in faster transaction confirmation.': 'Netzwerkgebühren variieren je nach Auslastung der Blockchain. Höhere Netzwerkgebühren führen zu einer schnelleren Bestätigung der Transaktion.',
      'Never share your seed phrase with anyone. Anyone with access to your seed phrase can control your wallet.': 'Teilen Sie Ihre Seed-Phrase niemals mit jemandem. Jeder, der Zugriff auf Ihre Seed-Phrase hat, kann Ihr Wallet kontrollieren.',
