      'No. PruneBit is transparent about all fees.': 'Nein. PruneBit ist bei allen Gebühren transparent.',
      'No. PruneBit is transparent about all fees. The fees shown above are the only fees you will pay. There are no account maintenance fees, no deposit fees, and no withdrawal fees beyond the network fee.': 'Nein. PruneBit ist bei allen Gebühren transparent. Die oben genannten Gebühren sind die einzigen Gebühren, die Sie zahlen. Es gibt keine Kontoführungsgebühren, keine Einzahlungsgebühren und keine Abhebungsgebühren über die Netzwerkgebühr hinaus.',
