      'If using Bitcoin, you can use RBF (Replace-By-Fee) to speed it up': 'Если вы используете Bitcoin, можете применить RBF (Replace-By-Fee) для ускорения',
      'If you are new to cryptocurrency, we recommend reading our Terms of Service and Privacy Policy first.': 'Если вы новичок в криптовалюте, рекомендуем сначала ознакомиться с нашими Условиями обслуживания и Политикой конфиденциальности.',
      'If you forgot your password but have your seed phrase, you can import your wallet using the seed phrase and set a new password. Go to import.html and select "Mnemonic Phrase".': 'Если вы забыли пароль, но у вас есть сид-фраза, вы можете импортировать кошелек с помощью сид-фразы и установить новый пароль. Перейдите к import.html и выберите «Мнемоническая фраза».',
      'If you have your password, you can still access your wallet. However, if you lose both your password and seed phrase, your wallet cannot be recovered. This is why it is crucial to back up your seed phrase in a secure location.': 'Если у вас есть пароль, вы по-прежнему можете получить доступ к кошельку. Однако если вы потеряете и пароль, и сид-фразу, кошелек восстановить невозможно. Именно поэтому крайне важно хранить резервную копию сид-фразы в безопасном месте.',
