      'Navigate to Create Wallet': 'Перейдите к созданию кошелька',
      'Navigate to the "Address Check" page from the dashboard or main menu.': 'Перейдите на страницу «Проверка адресов» с панели управления или из главного меню.',
      'Network fees fluctuate based on blockchain congestion. When many users are transacting simultaneously, fees increase due to higher demand for block space. During quiet periods, fees are lower. Bitcoin and Ethereum typically have the most variable fees.': 'Сетевые комиссии колеблются в зависимости от загруженности блокчейна. Когда многие пользователи совершают транзакции одновременно, комиссии растут из-за повышенного спроса на место в блоке. В периоды затишья комиссии ниже. У Bitcoin и Ethereum обычно самые изменчивые комиссии.',
      'Network fees vary depending on blockchain congestion. Higher network fees result in faster transaction confirmation.': 'Сетевые комиссии меняются в зависимости от загруженности блокчейна. Более высокие сетевые комиссии приводят к более быстрому подтверждению транзакции.',
      'Never share your seed phrase with anyone. Anyone with access to your seed phrase can control your wallet.': 'Никогда не сообщайте свою сид-фразу никому. Любой, у кого есть доступ к вашей сид-фразе, может управлять вашим кошельком.',
