      'New Users': 'Новые пользователи',
      'No Wallet. No Tracking. No KYC.': 'Никакого кошелька. Никакого отслеживания. Никакого KYC.',
      'No addresses found': 'Адреса не найдены',
      'No incidents': 'Нет инцидентов',
      'No storage of private keys on our servers': 'Никакого хранения приватных ключей на наших серверах',
      'No. PruneBit is transparent about all fees.': 'Нет. PruneBit прозрачен в отношении всех комиссий.',
      'No. PruneBit is transparent about all fees. The fees shown above are the only fees you will pay. There are no account maintenance fees, no deposit fees, and no withdrawal fees beyond the network fee.': 'Нет. PruneBit прозрачен в отношении всех комиссий. Указанные выше комиссии — единственные, которые вы будете платить. Нет комиссий за обслуживание счета, комиссий за депозит или комиссий за вывод, кроме сетевой комиссии.',
      'Non-urgent transactions': 'Несрочные транзакции',
