      'If you are new to cryptocurrency, we recommend reading our Terms of Service and Privacy Policy first.': 'Si es nuevo en el mundo de las criptomonedas, le recomendamos leer primero nuestros Términos de servicio y la Política de privacidad.',
      'If you forgot your password but have your seed phrase, you can import your wallet using the seed phrase and set a new password. Go to import.html and select "Mnemonic Phrase".': 'Si olvidó su contraseña pero tiene su frase semilla, puede importar su billetera usando la frase semilla y establecer una nueva contraseña. Vaya a import.html y seleccione "Frase mnemotécnica".',
