      'Navigate to the "Address Check" page from the dashboard or main menu.': 'Navegue a la página "Verificación de direcciones" desde el panel o el menú principal.',
      'Network fees fluctuate based on blockchain congestion. When many users are transacting simultaneously, fees increase due to higher demand for block space. During quiet periods, fees are lower. Bitcoin and Ethereum typically have the most variable fees.': 'Las comisiones de red fluctúan según la congestión de la blockchain. Cuando muchos usuarios transaccionan simultáneamente, las comisiones aumentan debido a la mayor demanda de espacio en bloque. Durante los períodos de calma, las comisiones son más bajas. Bitcoin y Ethereum suelen tener las comisiones más variables.',
      'Network fees vary depending on blockchain congestion. Higher network fees result in faster transaction confirmation.': 'Las comisiones de red varían según la congestión de la blockchain. Las comisiones de red más altas dan como resultado una confirmación más rápida de la transacción.',
      'Never share your seed phrase with anyone. Anyone with access to your seed phrase can control your wallet.': 'Nunca comparta su frase semilla con nadie. Cualquier persona con acceso a su frase semilla puede controlar su billetera.',
