      'If you forgot your password but have your seed phrase, you can import your wallet using the seed phrase and set a new password. Go to import.html and select "Mnemonic Phrase".': 'Se hai dimenticato la password ma hai la tua frase seed, puoi importare il tuo portafoglio usando la frase seed e impostare una nuova password. Vai a import.html e seleziona "Frase mnemonica".',
