      'When you send or exchange crypto, the following fees apply. Network fees are paid to miners/validators to confirm your transaction on the blockchain.': 'Quando invii o scambi criptovalute, si applicano le seguenti commissioni. Le commissioni di rete vengono pagate ai miner/validatori per confermare la tua transazione sulla blockchain.',
